def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    remaining = 100 - n
    if remaining == 1:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1

    # Has the opponent ever defected immediately after we defected?
    # If this is zero, defects are likely unprovoked or forgiving, so we may test/exploit.
    punish = 0
    if n > 1:
        for i in range(1, n):
            if history[i - 1][0] == 'D' and history[i][1] == 'D':
                punish += 1

    trailing = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            trailing += 1
        else:
            break

    recent_start = n - 5
    if recent_start < 0:
        recent_start = 0
    recent_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_d += 1
    recent_c = (n - recent_start) - recent_d

    # Probe and exploit opponents that have not punished our defects.
    if punish == 0:
        # Completely clean opponent: start with a safe probe: C,C,C,D,C,D,D,...
        if opp_d == 0:
            if n < 3:
                return 'C'
            if n == 3:
                return 'D'
            if n == 4:
                return 'C'
            return 'D'

        # Almost clean and currently cooperative: a limited safe exploit test.
        if opp_d <= 1 and n >= 6 and remaining > 2 and last_opp == 'C' and recent_c >= 4:
            return 'D'

    # Detect likely persistent defectors and answer with D.
    high = False

    # Unconditional or very recent all-defect behavior.
    if opp_d == n and n >= 3:
        high = True
    if recent_d == 5:
        high = True
    if opp_d >= 3 and n >= 6 and opp_d * 2 >= n:
        high = True
    if trailing >= 5 and opp_d * 2 >= n:
        high = True

    if high:
        return 'D'

    if last_opp == 'D':
        # Near the end, avoid triggering a final punishment unless clearly justified.
        if remaining == 2:
            return 'C'

        # If an opponent D-streak has just begun while we were cooperating,
        # defect once; otherwise forgive to break cycles.
        if trailing == 1 and (n == 1 or history[-2][0] == 'C'):
            return 'D'

        return 'C'

    return 'C'
